import sys
import json
import os
import requests
from urllib.parse import urljoin, urlencode

def load_token_cache():
    cache_path = os.path.expanduser("~/.quote_client_token.json")
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            try:
                data = json.load(f)
                return data.get('access_token'), data.get('expires_in')
            except json.JSONDecodeError:
                pass
    return None, None

def save_token_cache(token, expires_in):
    cache_path = os.path.expanduser("~/.quote_client_token.json")
    data = {'access_token': token, 'expires_in': expires_in}
    with open(cache_path, 'w') as f:
        json.dump(data, f)

def get_access_token(base_url, client_id, client_secret):
    token_url = urljoin(base_url, '/oauth/token')
    data = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    }
    response = requests.post(token_url, data=data)
    print(f"POST {token_url} -> {response.status_code}")
    if response.status_code != 200:
        print(f"error: Failed to obtain token: {response.status_code}")
        sys.exit(1)
    return response.json().get('access_token')

def get_quote(base_url, access_token, symbol):
    quote_url = urljoin(base_url, f'/quote?symbol={symbol}')
    headers = {'Authorization': f'Bearer {access_token}'}
    response = requests.get(quote_url, headers=headers)
    print(f"GET {quote_url} -> {response.status_code}")
    if response.status_code == 401:
        print("error: Unauthorized, retrying with new token...")
        new_token = get_access_token(base_url, client_id, client_secret)
        save_token_cache(new_token, 3600)
        response = requests.get(quote_url, headers={'Authorization': f'Bearer {new_token}'})
        print(f"GET {quote_url} -> {response.status_code}")
    if response.status_code < 200 or response.status_code >= 300:
        print(f"error: Failed to get quote: {response.status_code}")
        sys.exit(1)
    return response.json()

def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--base-url', required=True)
    parser.add_argument('--client-id', required=True)
    parser.add_argument('--client-secret', required=True)
    parser.add_argument('symbol', type=str)
    args = parser.parse_args()

    token, expires_in = load_token_cache()
    if token is None or (expires_in and int(expires_in) <= 0):
        token = get_access_token(args.base_url, args.client_id, args.client_secret)
        save_token_cache(token, 3600)

    quote = get_quote(args.base_url, token, args.symbol)
    print(f"{quote['symbol']} {quote['price']} {quote['currency']}")

if __name__ == "__main__":
    main()
